const ACCOUNTS = ["syn-a", "syn-b", "syn-c", "syn-d"];

function observe(lv: ReturnType<typeof createLocalVenue>) {
  return {
    stateHash: lv.venue.engine.stateHash(),
    outputHead: lv.venue.outputHead,
    journalHead: lv.venue.journal.head,
    commands: lv.venue.journal.lastSeq,
    executions: lv.venue.executions.length,
    publicMessages: lv.venue.publicTape.length,
  };
}

describe("D-1 golden hashes from the Milestone 11 book (9fcee80)", () => {
  it.each(["immediate", "batched"] as const)("D-1 seeded gateway flows (%s) reproduce the Milestone 11 hashes exactly", (publication) => {
    for (const seed of [11, 12, 13, 14]) {
      const lv = createLocalVenue({ accounts: ACCOUNTS, publication });
      let i = 0;
      for (const m of syntheticFlow(seed, 3_000, ACCOUNTS)) {
        lv.clock.advance(1);
        lv.gateway.handle(lv.tokens.get(m.accountId)!, m.message);
        if (publication === "batched" && ++i % 40 === 0) lv.venue.submit({ type: "publish" });
      }
      expect(observe(lv)).toEqual(GOLDEN_9FCEE80[`${publication}-${seed}`]);
    }
  }, 120_000);

  it("D-1 a large book with mostly hidden levels, then crossing flow, reproduces the Milestone 11 hashes exactly", () => {
    const lv = createLocalVenue({ accounts: ACCOUNTS, limits: { maxOpenOrders: 10_000, maxOrderNotional: 1e12, maxPositionLots: 1e12 } });
    for (let i = 0; i < 6_000; i++) {
      const sell = i % 2 === 1;
      lv.venue.submit({ type: "new-order", accountId: ACCOUNTS[i % 4]!, clientOrderId: `L${i}`, instrumentId: "SYN-ALPHA", side: sell ? "sell" : "buy", orderType: "limit", priceTicks: sell ? 4_003 + (i % 390) : 3_997 - (i % 390), qtyLots: 100 + (i % 7), tif: "gtc", visibility: i % 3 === 0 ? "displayed" : "hidden", postOnly: false, stp: "cancel-maker" });
    }
    for (const m of syntheticFlow(99, 4_000, ACCOUNTS)) {
      lv.clock.advance(1);
      lv.gateway.handle(lv.tokens.get(m.accountId)!, m.message);
    }
    expect(observe(lv)).toEqual(GOLDEN_9FCEE80["large-book-hidden"]);
  }, 120_000);
});
